    v3 ^= b;
    Z_SIP_ROUND(v0, v1, v2, v3);
    v0 ^= b;
    v2 ^= 0xff;
    Z_SIP_ROUND(v0, v1, v2, v3);
    Z_SIP_ROUND(v0, v1, v2, v3);
    Z_SIP_ROUND(v0, v1, v2, v3);
    return v0 ^ v1 ^ v2 ^ v3;
